/* Short tutorials, accessible without an account. */
(() => {
  'use strict';
  const topics={
    start:{title:'Mes trois premiers gestes',steps:[['Je rejoins mon club','Ouvrez le lien ou le code reçu du club, créez votre compte puis connectez-vous. Une invitation valide vous donne accès au club.'],['Je retrouve ma famille','Dans Ma famille, retrouvez les enfants rattachés à votre compte. Le responsable du club effectue ou corrige ce rattachement dans Accès et familles.'],['Je réponds au prochain événement','Ouvrez un match ou un entraînement, indiquez la présence et le transport à l’aller puis au retour. Une réponse par trajet suffit.']]},
    family:{title:'Répondre pour mon enfant',steps:[['Présent, absent ou à confirmer','Choisissez la disponibilité de votre enfant. Le coach sait ainsi sur qui compter. Une convocation indique ensuite l’équipe retenue.'],['Aller et retour séparément','Pour chaque trajet, choisissez « Cherche une place », réservez une place si elle est disponible, ou indiquez « Avec ses parents ».'],['La réservation est pour l’enfant','Vous réservez pour Inès dans le covoiturage de l’événement. Lumo ne vous demande pas de choisir sa voiture. Les familles se coordonnent au rendez-vous.']]},
    cars:{title:'Proposer une voiture',steps:[['Mon véhicule et ses passagers','Indiquez le conducteur, de qui vous êtes le parent, la taille de la voiture et les enfants déjà présents. Le conducteur occupe toujours une place.'],['Mes places, pour chaque trajet','Activez l’aller, le retour ou les deux, et précisez les places proposées. Lumo montre les places disponibles et les enfants qui attendent encore un transport.'],['Voiture de secours','Si vous pouvez venir seulement en cas de besoin, choisissez la voiture de secours. Une proposition de regroupement reste à confirmer : une voiture ne disparaît jamais sans décision du conducteur ou du responsable.']]},
    volunteer:{title:'Donner un coup de main',steps:[['Je choisis une mission','Dans Coups de main, retrouvez arbitrage, table de marque, buvette, goûter, gâteaux, salle et maillots.'],['Je me porte volontaire','Inscrivez-vous sur une mission disponible. Votre nom apparaît dans la liste des volontaires, afin que le club voie ce qui manque.'],['Je préviens si je ne peux plus','Retirez votre participation pour libérer la mission et permettre à une autre personne de s’inscrire.']]},
    coach:{title:'Préparer un événement avec le club',steps:[['Je prépare le rendez-vous','Créez le match ou entraînement, choisissez les groupes et sous-groupes, puis renseignez horaire, lieu et rendez-vous. Relisez les données importées de FFHandball.'],['Je publie les convocations','Consultez les disponibilités, sélectionnez les joueurs et leur équipe, puis publiez. Les familles reçoivent une alerte dans Lumo et sur leurs appareils activés.'],['Je vérifie l’organisation','Contrôlez séparément l’aller et le retour, les réponses manquantes et les bénévoles. Les droits coach et responsable sont attribués par le club, pas par un simple bouton de mode.']]},
    install:{title:'Installer Lumo sur mon téléphone',steps:[['Android','Ouvrez Lumo dans Chrome. Dans le menu ⋮, choisissez « Installer l’application » ou « Ajouter à l’écran d’accueil ». Si un bouton Installer apparaît dans Lumo, vous pouvez aussi l’utiliser.'],['iPhone / iPad','Ouvrez Lumo dans Safari. Touchez Partager, puis « Sur l’écran d’accueil ». Ouvrez ensuite Lumo depuis cette nouvelle icône. Aucun compte Apple développeur n’est nécessaire pour cette installation.'],['Ordinateur','Sur un navigateur compatible, utilisez l’icône d’installation dans la barre d’adresse ou le menu. Vous pouvez aussi simplement utiliser le site.']]},
    notifications:{title:'Recevoir les alertes',steps:[['J’active volontairement mon appareil','Connectez-vous, ouvrez Notifications, puis touchez « Activer les notifications ». Acceptez la demande du navigateur. Répétez cette opération sur chaque appareil souhaité.'],['Je teste et choisis mes rappels','« Envoyer un test » ajoute une alerte dans Lumo et l’envoie aux appareils activés sous environ une minute. Les rappels arrivent la veille et deux heures avant le rendez-vous ; vous pouvez les désactiver.'],['Si rien n’arrive','Sur iPhone/iPad, utilisez Lumo installé sur l’écran d’accueil avec iOS/iPadOS 16.4 ou plus récent. Vérifiez les permissions, le mode concentration et la connexion. Les alertes restent accessibles dans Lumo ; les restrictions du téléphone peuvent retarder le push.']]},
    privacy:{title:'Mon compte et mes données',steps:[['Des accès liés au club','Seuls les membres autorisés du club accèdent à ses informations. Les parents répondent pour leur famille ; les coachs et responsables disposent des droits nécessaires à l’organisation.'],['Un appareil partagé','Déconnectez-vous lorsque vous quittez un ordinateur partagé. Désactivez les notifications de cet appareil si d’autres personnes l’utilisent. Les notifications visibles sur l’écran verrouillé n’affichent pas le nom des enfants.'],['Corriger ou supprimer','Demandez au responsable du club la correction, la dissociation ou la suppression de votre fiche. Une connexion internet est nécessaire pour enregistrer les réponses partagées ; le mode démo reste séparé du club réel.']]}
  };
  function body(topic){return `<ol class="lumo-help-steps">${topic.steps.map(([title,text],i)=>`<li><span class="help-number" aria-hidden="true">${i+1}</span><div><h3>${title}</h3><p>${text}</p></div></li>`).join('')}</ol>`;}
  function render(role='parent'){const keys=role==='coach'||role==='admin'?Object.keys(topics):Object.keys(topics).filter(key=>key!=='coach');return `<section class="lumo-help"><div class="page-head"><div><p class="eyebrow">Un coup de main, quand vous en avez besoin</p><h1>Bien démarrer avec Lumo</h1><p>Des guides courts pour s’organiser avec le club.</p></div></div><article class="card help-first"><h2>${topics.start.title}</h2>${body(topics.start)}</article><div class="grid">${keys.filter(key=>key!=='start').map(key=>`<article class="card"><h2>${topics[key].title}</h2><p>${topics[key].steps[0][1]}</p><button data-lumo-help="${key}">Voir les 3 étapes</button></article>`).join('')}</div></section>`;}
  function open(key='start'){
    const topic=topics[key]||topics.start;let dialog=document.getElementById('lumo-help-dialog');
    if(!dialog){dialog=document.createElement('dialog');dialog.id='lumo-help-dialog';document.body.append(dialog);dialog.addEventListener('click',event=>{if(event.target.closest('[data-help-close]'))dialog.close();});}
    dialog.innerHTML=`<div class="dialog-head"><h2 id="lumo-help-title">${topic.title}</h2><button aria-label="Fermer l’aide" data-help-close>✕</button></div><div class="dialog-body">${body(topic)}<div class="actions"><button class="primary" data-help-close>J’ai compris</button></div></div>`;dialog.setAttribute('aria-labelledby','lumo-help-title');if(!dialog.open)dialog.showModal();
  }
  function banner(userId='demo'){const seen=localStorage.getItem('lumo-guide-seen:'+userId);return seen?'':`<aside class="card help-welcome"><div><p class="eyebrow">Bienvenue dans Lumo</p><h2>Votre premier match, en trois gestes</h2><p>Rejoindre le club, retrouver sa famille, répondre au trajet.</p></div><div class="actions"><button data-lumo-help="start">Me guider</button><button data-help-dismiss="${String(userId).replace(/[^a-zA-Z0-9-]/g,'')}">Plus tard</button></div></aside>`;}
  document.addEventListener('click',event=>{const button=event.target.closest('[data-lumo-help]');if(button)open(button.dataset.lumoHelp);const dismiss=event.target.closest('[data-help-dismiss]');if(dismiss){localStorage.setItem('lumo-guide-seen:'+dismiss.dataset.helpDismiss,'1');dismiss.closest('.help-welcome')?.remove();}});
  window.LumoHelp={render,open,banner,topics};
})();
